      'Это не программа первого выбора при любой усталости. Если анализы в норме, а жалобы сохраняются, врач ищет другую причину, а не предлагает инфузию "на всякий случай".',
      '## Когда инфузионная поддержка не подходит',
      'Есть ситуации, где от капельницы стоит отказаться или отложить её:',
