      'На интенсивных тренировках организм тратит ресурсы быстро. Мышцы берут аминокислоты на восстановление, обмен веществ расходует витамины группы B, нервная система и мышцы требуют магний и калий. Часть микроэлементов уходит с потом, часть не успевает закрыться обычным рационом.',
      'Если такой режим длится долго, вы начинаете замечать знакомые сигналы: усталость держится дольше, выносливость падает, мышцы восстанавливаются медленно, а сил на следующую тренировку уже меньше. В этот момент многие добавляют поддержку извне.',
      '## Что дают БАДы',
      'БАДы закрывают базовую поддержку. Спортсмены чаще всего используют протеин, аминокислотные комплексы, электролиты, витамины и минералы. Такой формат удобен, если вы держите питание под контролем и хотите поддерживать организм на постоянной основе.',
      'Но у добавок есть предел. Они проходят через пищеварительную систему, а скорость усвоения зависит от рациона, ЖКТ и выраженности дефицита. Если нагрузка высокая, а ресурс просел заметно, БАДы не всегда дают тот темп восстановления, который вам нужен.',
      '## Когда спортсмены используют капельницы',
      'Капельницы выбирают в тех случаях, когда организму нужна более точная и быстрая поддержка. При инфузионной терапии врач вводит раствор внутривенно, поэтому вещества сразу попадают в кровоток и не зависят от пищеварения.',
      'Спортсмены приходят на такие программы после соревнований, в период плотной подготовки, при подтвержденных дефицитах и после серий нагрузок, когда усталость уже мешает тренироваться в нужном режиме. В состав могут входить аминокислоты, витамины группы B, витамин C, магний и другие компоненты под конкретную задачу.',
      'Капельница не работает сама по себе. Врач сначала оценивает анализы, жалобы и текущую нагрузку, а потом подбирает состав. Такой подход дает больше смысла, чем случайный выбор по названию.',
      '## Когда это действительно имеет смысл',
      'Если вы тренируетесь нерегулярно и питание закрывает основные потребности, БАДов часто хватает. Если вы тренируетесь 3-5 раз в неделю, готовитесь к старту, восстанавливаетесь между тяжелыми сессиями или видите дефициты в анализах, врач может предложить капельницу как часть плана восстановления.',
      'Обычно схема выглядит так: базовую поддержку вы держите на питании и добавках, а капельницы используете точечно, когда нагрузка выше обычной или организму нужно быстрее вернуться в рабочее состояние.',
      'В BIORISE есть программы для спортсменов, которые помогают восстановиться после интенсивных тренировок, восполнить дефициты и вернуть тонус. Врач подбирает состав под ваши анализы, уровень нагрузки и цель на ближайший период.',
