      'У таблеток есть плюс: вы не приходите на инфузию и не проходите процедуру в клинике. Но этот вариант работает только тогда, когда организм переносит препарат и успевает его усваивать.',
      '## Когда врач обсуждает капельницу железа',
      'Курс внутривенного железа обычно рассматривают в нескольких ситуациях.',
      '### Таблетки вызывают побочные эффекты',
      'Некоторые пациенты не могут закончить курс из-за тошноты, боли в животе, запора или диареи. Если человек срывает лечение из-за побочных реакций, врач ищет другой путь.',
      '### Железо плохо всасывается',
