      '### Есть хронические заболевания',
      'Капельницы часто используют у пациентов с хронической болезнью почек, сердечной недостаточностью, воспалительными заболеваниями кишечника и другими состояниями, где дефицит железа повторяется или ведёт себя нестабильно.',
