      '- витамин B12 и фолиевая кислота по показаниям.',
      'Врач ищет не только дефицит, но и его причину. Если человек теряет железо из-за кровопотери или плохо его всасывает, один курс не решит проблему надолго.',
      '## Почему нельзя смотреть только на ферритин',
      'Ферритин относится к белкам острой фазы. При инфекции или воспалении его уровень может подняться и спрятать реальный дефицит.',
      'Поэтому врач сверяет ферритин с остальными анализами, жалобами и историей болезни. Один показатель без контекста часто даёт неверную картину.',
      '## Как проходит капельница железа',
      'Современные препараты вводят внутривенно в клинике. Перед процедурой врач проверяет показания, исключает противопоказания, рассчитывает дозу и решает, сколько инфузий понадобится.',
      'Во время введения медперсонал следит за самочувствием пациента. После процедуры вас могут оставить под наблюдением на короткое время.',
      'Дома такие процедуры не проводят. Для внутривенного железа нужен медицинский контроль.',
      '## Есть ли противопоказания',
      'Да. Капельница железа подходит не всем.',
      'Врач отдельно оценивает аллергию на препарат, избыток железа, острые инфекции и другие состояния, при которых лечение лучше отложить или заменить.',
      '## Когда повторно проверяют анализы',
      'После курса врач обычно назначает контроль. Чаще всего он повторно смотрит гемоглобин, ферритин и показатели обмена железа.',
      'Срок зависит от препарата, глубины дефицита и общей клинической ситуации. Сдавать анализы раньше, чем назначил врач, смысла мало.',
      '## Почему важно найти причину низкого ферритина',
