      'Повышение АЛТ и АСТ означает, что клетки, в которых содержатся эти ферменты, повреждены и высвобождают их в кровь. Частые причины - вирусные гепатиты, жировая болезнь печени, злоупотребление алкоголем, приём отдельных лекарственных препаратов и биологически активных добавок в высоких дозах. Если АСТ повышен заметно сильнее АЛТ, врач может дополнительно оценить состояние сердца и мышц, поскольку причина не всегда печёночная.',
      '## Насколько сильно повышение говорит о серьёзности проблемы',
      'Степень повышения ферментов не всегда напрямую связана с тяжестью заболевания: при остром вирусном гепатите показатели могут вырасти в десятки раз, а при хронической жировой болезни печени - оставаться повышенными незначительно на протяжении долгого времени. Именно поэтому по одному результату диагноз не ставят - врач сопоставляет цифры с жалобами, историей и другими анализами.',
      '## Как подготовиться к сдаче',
      'Кровь сдают натощак, через 8-12 часов после последнего приёма пищи. За 1-2 дня до анализа стоит отказаться от алкоголя, жирной пищи и интенсивных физических нагрузок - они способны временно исказить результат.',
      '## Что делать при повышенном результате',
      'Однократное повышение АЛТ и АСТ - повод пересдать анализ и обсудить с врачом дальнейшее обследование: чаще всего это УЗИ печени и дополнительные лабораторные показатели. Если причиной становится накопленная нагрузка на печень, врач может в числе прочего обсудить [капельницу для печени](/articles/kapelnitsa-dlya-pecheni-dlya-chego-naznachayut/) как часть комплексной поддержки, но это не заменяет лечение основной причины повышения ферментов.',
