      '## Что такое СРБ',
      'СРБ (С-реактивный белок) - белок, который печень начинает вырабатывать в ответ на воспаление, повреждение тканей или инфекцию. Его уровень повышается в течение нескольких часов после начала воспалительного процесса, что делает СРБ одним из самых быстрых индикаторов острого воспаления.',
      '## Когда назначают анализ',
