      '## Как подготовиться к сдаче',
      'Кровь на СРБ сдают натощак, обычно утром. Накануне желательно избегать интенсивных физических нагрузок и жирной пищи, поскольку они способны временно повлиять на результат.',
      '## Что делать при повышенном результате',
